window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-5a33c4b39d0a9772"]={"versions": [{"id": "FIG-5a33c4b39d0a9772", "releases": ["R4.1.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Konzeptionelles Kontext- und Strukturdiagramm zur Darstellung der Themenfelder und Anforderungsquellen für AUTOSAR-Authoring-Werkzeuge im Rahmen von AUTOSAR_TR_InteractionWithBehavioralModels. Ein zentraler Block repräsentiert die Werkzeugdomäne, umgeben von vier peripheren Themenaspekten.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm umfasst fünf Hauptelemente:</p>\n<ul class=\"fig-list\"><li>Zentraler rechteckiger Block: <code>AUTOSAR Authoring Tools</code>.\n</li><li>Vier abgerundete rechteckige Blöcke als Themen- und Einflussdomänen:\n<ul class=\"fig-list\"><li>Oben links: <code>Behavior Modeling Tools</code>\n</li><li>Oben rechts: <code>Graphical Notation</code>\n</li><li>Unten links: <code>Feature Definition</code>\n</li><li>Unten rechts: <code>Interoperability</code>\n</li></ul>\n</li><li>Vier gerichtete Pfeile weisen von den vier Eckblöcken auf den zentralen Block und sind jeweils mit dem Beziehungsbezeichner <code>Requirements</code> beschriftet.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Das Diagramm modelliert keinen zeitlichen oder nachrichtenbasierten Ablauf. Es stellt eine statische Abhängigkeits- bzw. Anforderungsbeziehung dar, bei der Anforderungen aus den vier Domänen („Behavior Modeling Tools“, „Graphical Notation“, „Feature Definition“, „Interoperability“) auf AUTOSAR-Authoring-Tools einwirken bzw. für diese spezifiziert werden.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Schaubild dient der Strukturierung des Themenspektrums und verweist konzeptionell auf separate AUTOSAR-Spezifikationsdokumente für jeden der dargestellten Aspekte. Entwickler und Tool-Hersteller müssen Anforderungen aus allen vier Domänen berücksichtigen, um standardkonforme AUTOSAR-Authoring-Werkzeuge bereitzustellen.</p>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-331eced6fcf2ecbc", "releases": ["R4.2.2", "R4.3.1", "R18-10_R4.4.0_R1.5.0"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Konzeptionelles Kontext- und Strukturdiagramm zur Darstellung der Themenfelder und Anforderungsquellen für AUTOSAR-Authoring-Werkzeuge im Rahmen von AUTOSAR_TR_InteractionWithBehavioralModels. Ein zentraler Block repräsentiert die Werkzeugdomäne, umgeben von vier peripheren Themenaspekten.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm umfasst fünf Hauptelemente:</p>\n<ul class=\"fig-list\"><li>Zentraler rechteckiger Block: <code>AUTOSAR Authoring Tools</code>.\n</li><li>Vier abgerundete rechteckige Blöcke als Themen- und Einflussdomänen:\n<ul class=\"fig-list\"><li>Oben links: <code>Behavior Modeling Tools</code>\n</li><li>Oben rechts: <code>Graphical Notation</code>\n</li><li>Unten links: <code>Feature Definition</code>\n</li><li>Unten rechts: <code>Interoperability</code>\n</li></ul>\n</li><li>Vier gerichtete Pfeile weisen von den vier Eckblöcken auf den zentralen Block und sind jeweils mit dem Beziehungsbezeichner <code>Require-</code> beschriftet.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Das Diagramm modelliert keinen zeitlichen oder nachrichtenbasierten Ablauf. Es stellt eine statische Abhängigkeits- bzw. Anforderungsbeziehung dar, bei der Anforderungen aus den vier Domänen („Behavior Modeling Tools“, „Graphical Notation“, „Feature Definition“, „Interoperability“) auf AUTOSAR-Authoring-Tools einwirken bzw. für diese spezifiziert werden.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Schaubild dient der Strukturierung des Themenspektrums und verweist konzeptionell auf separate AUTOSAR-Spezifikationsdokumente für jeden der dargestellten Aspekte. Entwickler und Tool-Hersteller müssen Anforderungen aus allen vier Domänen berücksichtigen, um standardkonforme AUTOSAR-Authoring-Werkzeuge bereitzustellen.</p>", "model": "gemini-3.8-flash (via agy)"}], "trans": [{"from": "FIG-5a33c4b39d0a9772", "to": "FIG-331eced6fcf2ecbc", "fr": "R4.1.3", "tr": "R4.2.2", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\"><li>Pfeilbeschriftung an allen vier Beziehungskanten von „Requirements“ zu „Require-“ verkürzt/umgebrochen.\n</li></ul>"}]};
